def add_or_update_inventory_record(record):
    """
    Keep each detected physical food as a separate inventory item.

    Camera records use an instance_id built from the uploaded image
    and detection index. Re-clicking Add for the same detection
    updates that same row instead of creating an accidental duplicate.

    Different detections remain separate even when they have the same
    food type and the same condition.
    """
    instance_id = record.get(
        "instance_id"
    )

    if instance_id:
        for index, existing in enumerate(
            st.session_state.inventory
        ):
            if (
                existing.get("instance_id")
                == instance_id
            ):
                st.session_state.inventory[index] = (
                    record.copy()
                )
                return "updated"

    st.session_state.inventory.append(
        record.copy()
    )

    return "added"


def detection_to_inventory_record(
    detection,
    image_id
):
    record = inventory_record_from_detection(
        detection
    )

    record["instance_id"] = (
        f"{image_id}:"
        f"{detection.get('detection_index', 0)}"
    )

    return record


def stage_group_labels(
    inventory,
    stage_name
):
    names = [
        str(record.get("item", "")).strip()
        for record in inventory
        if str(
            record.get("stage", "")
        ).strip().lower()
        == stage_name.lower()
    ]

    counts = Counter(
        name
        for name in names
        if name
    )

    labels = []

    for item in sorted(
        counts,
        key=str.lower
    ):
        count = counts[item]

        labels.append(
            f"{item} ×{count}"
            if count > 1
            else item
        )

    return labels


def clamp_probability(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return 0.0

    return max(
        0.0,
        min(1.0, value)
    )


def percent_text(value, decimals=1):
    value = clamp_probability(value)

    return (
        f"{value * 100:.{decimals}f}%"
    )


def friendly_condition(stage):
    stage = str(stage).strip().lower()

    mapping = {
        "fresh": "Fresh",
        "medium": "Use Soon",
        "rotten": "Do Not Use",
        "not assessed": "Not Assessed"
    }

    return mapping.get(
        stage,
        str(stage).title()
    )


def friendly_action(stage):
    stage = str(stage).strip().lower()

    mapping = {
        "fresh": "Use normally",
        "medium": "Prioritise this food",
        "rotten": "Do not use in recipes",
        "not assessed": "Condition not assessed"
    }

    return mapping.get(
        stage,
        "Available"
    )


def friendly_source(source):
    source = str(source).strip().lower()

    if source in {"cv", "computer_vision"}:
        return "Camera"

    if source == "manual":
        return "Manual"

    return str(source).replace("_", " ").title()


def status_icon(stage):
    stage = str(stage).strip().lower()

    mapping = {
        "fresh": "🟢",
        "medium": "🟠",
        "rotten": "⚫",
        "not assessed": "⚪"
    }

    return mapping.get(
        stage,
        "⚪"
    )


def split_items(value):
    if value is None:
        return []

    text = str(value).strip()

    if not text or text.lower() == "nan":
        return []

    return [
        item.strip()
        for item in text.split("|")
        if item.strip()
    ]


def clean_metadata(value):
    if value is None:
        return None

    try:
        if pd.isna(value):
            return None
    except Exception:
        pass

    text = str(value).strip()

    if not text or text.lower() == "nan":
        return None

    return text


