def show_candidate_card(
    row,
    number
):
    coverage = clamp_probability(
        row.get(
            "inventory_coverage",
            0.0
        )
    )

    matched = split_items(
        row.get(
            "matched_inventory",
            ""
        )
    )

    pantry = split_items(
        row.get(
            "pantry_ingredients",
            ""
        )
    )

    unavailable = split_items(
        row.get(
            "unavailable_ingredients",
            ""
        )
    )

    total_time = clean_metadata(
        row.get(
            "total"
        )
    )

    rating = clean_metadata(
        row.get(
            "rating"
        )
    )

    category = clean_metadata(
        row.get(
            "category"
        )
    )

    with st.container(border=True):
        title_col, match_col = st.columns(
            [3, 1]
        )

        with title_col:
            st.subheader(
                f"{number}. {row['name']}"
            )

            if category:
                st.caption(
                    category
                )

        with match_col:
            st.metric(
                "Kitchen match",
                percent_text(
                    coverage,
                    decimals=0
                )
            )

        st.progress(
            coverage
        )

        info = []

        if total_time:
            info.append(
                f"⏱ {total_time}"
            )

        if rating:
            info.append(
                f"⭐ {rating}"
            )

        if bool(
            row.get(
                "priority_used",
                False
            )
        ):
            info.append(
                "🟠 Uses food that should be used soon"
            )

        if info:
            st.caption(
                "   •   ".join(info)
            )

        left, right = st.columns(2)

        with left:
            st.markdown(
                "**Uses from your kitchen**"
            )

            if matched:
                for ingredient in matched:
                    st.write(
                        f"✓ {ingredient}"
                    )
            else:
                st.caption(
                    "No direct kitchen match listed."
                )

            if pantry:
                st.markdown(
                    "**Basic pantry items**"
                )

                for ingredient in pantry:
                    st.write(
                        f"• {ingredient}"
                    )

        with right:
            if unavailable:
                st.markdown(
                    "**Original recipe extras**"
                )

                for ingredient in unavailable:
                    st.write(
                        f"• {ingredient}"
                    )

                st.caption(
                    "These will be removed or adapted "
                    "before the final recipe is shown."
                )

            else:
                st.markdown(
                    "**Ready for your kitchen**"
                )

                st.write(
                    "✓ No extra recipe ingredients "
                    "need to be adapted."
                )


def show_recipe_checks(report):
    checks = [
        (
            "Recipe has a complete title, "
            "ingredient list and steps",
            report.get(
                "structure_valid",
                False
            )
        ),
        (
            "Uses only permitted ingredients",
            report.get(
                "allowed_ingredients_valid",
                False
            )
        ),
        (
            "Avoids food marked as unusable",
            report.get(
                "excluded_ingredients_valid",
                False
            )
        ),
        (
            "Uses all foods that should be "
            "prioritised",
            report.get(
                "priority_compliant",
                False
            )
        ),
        (
            "Priority-food information is consistent",
            report.get(
                "priority_field_consistent",
                False
            )
        )
    ]

    for label, passed in checks:
        icon = (
            "✅"
            if passed
            else "❌"
        )

        st.write(
            f"{icon} {label}"
        )

    extra_rate = clamp_probability(
        report.get(
            "hallucination_rate",
            0.0
        )
    )

    st.markdown(
        "**Extra ingredient rate**"
    )

    st.progress(
        extra_rate
    )

    st.caption(
        percent_text(
            extra_rate
        )
    )

    hallucinated = report.get(
        "hallucinated_ingredients",
        []
    )

    if hallucinated:
        st.write(
            "**Unexpected ingredients found:**",
            ", ".join(
                hallucinated
            )
        )




