def candidate_record(row):
    record = row.to_dict()

    # Convert NumPy scalar values to standard Python values
    # so Streamlit Session State stays simple.
    cleaned = {}

    for key, value in record.items():
        try:
            if pd.isna(value):
                cleaned[key] = None
                continue
        except Exception:
            pass

        if hasattr(value, "item"):
            try:
                value = value.item()
            except Exception:
                pass

        cleaned[key] = value

    return cleaned


