def render_recipe_result(event):
    adapted = event.get(
        "adapted"
    )

    report = event.get(
        "report"
    )

    if (
        adapted is not None
        and report is not None
        and report.get(
            "usable_recipe",
            False
        )
    ):
        with st.container(border=True):
            st.success(
                "✓ Checked for your kitchen"
            )

            st.subheader(
                f"🍽️ {adapted['title']}"
            )

            source_candidate = adapted.get(
                "source_candidate"
            )

            if source_candidate:
                st.caption(
                    "Adapted from: "
                    f"{source_candidate}"
                )

            st.markdown(
                "### Ingredients"
            )

            for ingredient in adapted[
                "ingredients"
            ]:
                st.write(
                    f"• {ingredient}"
                )

            st.markdown(
                "### How to make it"
            )

            for number, step in enumerate(
                adapted[
                    "steps"
                ],
                start=1
            ):
                st.write(
                    f"**{number}.** {step}"
                )

            if adapted.get(
                "adaptation_summary"
            ):
                st.markdown(
                    "### Why this works for your kitchen"
                )

                st.write(
                    adapted[
                        "adaptation_summary"
                    ]
                )

            priority_used = adapted.get(
                "priority_ingredients_used",
                []
            )

            if priority_used:
                st.info(
                    "This recipe helps use "
                    + ", ".join(
                        priority_used
                    )
                    + " before it deteriorates further."
                )

        with st.expander(
            "✅ View recipe checks"
        ):
            show_recipe_checks(
                report
            )

    else:
        st.warning(
            "I could not create an approved version "
            "of that recipe using only your current "
            "kitchen ingredients."
        )

        attempts = event.get(
            "attempts",
            []
        )

        if attempts:
            with st.expander(
                "View recipe check"
            ):
                for attempt in attempts:
                    st.write(
                        "Recipe:",
                        attempt.get(
                            "candidate"
                        )
                    )

                    st.write(
                        "Check:",
                        attempt.get(
                            "validation"
                        )
                    )


def process_recipe_action(
    action,
    recipe_inventory,
    recipes,
    vectorizer,
    recipe_matrix,
    user_message=None,
    requested_count=3
):
    append_chat_message(
        "user",
        user_message if user_message else action
    )

    if action == "🍳 Suggest some recipes":
        if not recipe_inventory[
            "available_ingredients"
        ]:
            append_chat_message(
                "assistant",
                (
                    "Your kitchen does not have any usable "
                    "ingredients yet. Add at least one food "
                    "first, then I can suggest recipes."
                )
            )
            return

        requested_count = max(
            1,
            min(
                int(requested_count),
                6
            )
        )

        try:
            # Retrieve a larger pool so that follow-up requests
            # can return NEW recipes instead of repeating the
            # first three results.
            retrieved = retrieve_recipes(
                recipe_inventory,
                recipes,
                vectorizer,
                recipe_matrix,
                top_n=100
            )

            constrained = apply_constraints(
                retrieved,
                recipe_inventory
            )

            usable_pool = (
                constrained[
                    constrained[
                        "decision"
                    ]
                    != "REJECT"
                ]
                .reset_index(
                    drop=True
                )
            )

            already_suggested = {
                str(name).strip().lower()
                for name in st.session_state.get(
                    "suggested_recipe_names",
                    []
                )
            }

            unseen_candidates = (
                usable_pool[
                    ~usable_pool[
                        "name"
                    ]
                    .astype(str)
                    .str.strip()
                    .str.lower()
                    .isin(
                        already_suggested
                    )
                ]
                .reset_index(
                    drop=True
                )
            )

            if unseen_candidates.empty:
                append_chat_message(
                    "assistant",
                    (
                        "I've already shown all suitable recipe "
                        "ideas I can find for your current "
                        "kitchen. Try adding another usable "
                        "ingredient if you want more options."
                    )
                )
                return

            usable_candidates = (
                unseen_candidates
                .head(
                    requested_count
                )
                .reset_index(
                    drop=True
                )
            )

            new_names = (
                usable_candidates[
                    "name"
                ]
                .astype(str)
                .tolist()
            )

            st.session_state.suggested_recipe_names.extend(
                new_names
            )

            # Remove duplicates while preserving order.
            st.session_state.suggested_recipe_names = list(
                dict.fromkeys(
                    st.session_state.suggested_recipe_names
                )
            )

            st.session_state.recipe_candidates = (
                usable_candidates
            )

            st.session_state.recipe_result = None
            st.session_state.selected_recipe = None

            priority_items = recipe_inventory[
                "priority_ingredients"
            ]

            returned_count = len(
                usable_candidates
            )

            remaining_count = max(
                0,
                len(unseen_candidates)
                - returned_count
            )

            if returned_count < requested_count:
                reply = (
                    f"I found only {returned_count} more suitable "
                    f"recipe{'s' if returned_count != 1 else ''} "
                    "for your current kitchen, so I'll show "
                    f"{'them' if returned_count != 1 else 'it'} below."
                )
            elif already_suggested:
                reply = (
                    f"Sure — here {'are' if returned_count != 1 else 'is'} "
                    f"{returned_count} more recipe"
                    f"{'s' if returned_count != 1 else ''} that I "
                    "haven't shown you yet."
                )
            elif priority_items:
                reply = (
                    f"I found {returned_count} recipe idea"
                    f"{'s' if returned_count != 1 else ''} for you. "
                    "I gave extra priority to food that should "
                    "be used soon."
                )
            else:
                reply = (
                    f"I found {returned_count} recipe idea"
                    f"{'s' if returned_count != 1 else ''} based on "
                    "what is already in your kitchen."
                )

            if remaining_count == 0:
                reply += (
                    " These are the last suitable new options "
                    "I can currently find."
                )

            append_chat_message(
                "assistant",
                reply
            )

            st.session_state.chat_events.append(
                {
                    "type": "candidates",
                    "role": "assistant",
                    "active": True,
                    "candidates": [
                        candidate_record(
                            row
                        )
                        for _, row
                        in usable_candidates.iterrows()
                    ]
                }
            )

            st.session_state.scroll_to_latest = True

        except Exception as error:
            append_chat_message(
                "assistant",
                (
                    "I couldn't search for recipes right now. "
                    f"Please try again. ({error})"
                )
            )

    elif action == "🟠 What should I use soon?":
        priority_items = recipe_inventory[
            "priority_ingredients"
        ]

        if priority_items:
            reply = (
                "These foods should be used first:\n"
                + "\n".join(
                    f"• {item}"
                    for item in priority_items
                )
                + "\n\nI'll prioritise them when "
                "suggesting recipes."
            )
        else:
            reply = (
                "Nothing in your kitchen is currently "
                "marked as 'Use Soon'."
            )

        append_chat_message(
            "assistant",
            reply
        )

    elif action == "🥕 What's in my kitchen?":
        available = recipe_inventory[
            "available_ingredients"
        ]

        excluded = recipe_inventory[
            "excluded_items"
        ]

        parts = []

        if available:
            parts.append(
                "Available:\n"
                + "\n".join(
                    f"• {item}"
                    for item in available
                )
            )
        else:
            parts.append(
                "There are no usable ingredients "
                "in My Kitchen yet."
            )

        if excluded:
            parts.append(
                "I will not use:\n"
                + "\n".join(
                    f"• {item}"
                    for item in excluded
                )
            )

        append_chat_message(
            "assistant",
            "\n\n".join(
                parts
            )
        )

    elif action == "💡 What can you do?":
        append_chat_message(
            "assistant",
            (
                "I can suggest recipes, show which foods "
                "should be used soon, or summarise what is "
                "currently in your kitchen."
            )
        )

def process_typed_message(
    message,
    recipe_inventory,
    recipes,
    vectorizer,
    recipe_matrix
):
    text = str(
        message
    ).strip()

    lower = text.lower()

    if not text:
        return

    recipe_words = [
        "recipe",
        "recipes",
        "cook",
        "cooking",
        "meal",
        "meals",
        "dish",
        "dishes",
        "what can i make",
        "what should i cook",
        "suggest"
    ]

    soon_words = [
        "use soon",
        "use first",
        "priority",
        "expire",
        "expiring",
        "going bad",
        "eat first"
    ]

    kitchen_words = [
        "what's in my kitchen",
        "what is in my kitchen",
        "my kitchen",
        "available",
        "what do i have",
        "inventory"
    ]

    help_words = [
        "help",
        "what can you do",
        "options",
        "how does this work"
    ]

    greeting_words = [
        "hi",
        "hello",
        "hey",
        "good morning",
        "good afternoon",
        "good evening"
    ]

    if any(
        phrase in lower
        for phrase in recipe_words
    ):
        # If the user gives a number, respect it.
        # Example: "suggest 2 more recipes" -> 2.
        count_match = re.search(
            r"\b([1-6])\b",
            lower
        )

        word_counts = {
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6
        }

        requested_count = 3

        if count_match:
            requested_count = int(
                count_match.group(1)
            )
        else:
            for word, count in word_counts.items():
                if re.search(
                    rf"\b{word}\b",
                    lower
                ):
                    requested_count = count
                    break

        process_recipe_action(
            "🍳 Suggest some recipes",
            recipe_inventory,
            recipes,
            vectorizer,
            recipe_matrix,
            user_message=text,
            requested_count=requested_count
        )

    elif any(
        phrase in lower
        for phrase in soon_words
    ):
        process_recipe_action(
            "🟠 What should I use soon?",
            recipe_inventory,
            recipes,
            vectorizer,
            recipe_matrix,
            user_message=text
        )

    elif any(
        phrase in lower
        for phrase in kitchen_words
    ):
        process_recipe_action(
            "🥕 What's in my kitchen?",
            recipe_inventory,
            recipes,
            vectorizer,
            recipe_matrix,
            user_message=text
        )

    elif any(
        phrase in lower
        for phrase in help_words
    ):
        process_recipe_action(
            "💡 What can you do?",
            recipe_inventory,
            recipes,
            vectorizer,
            recipe_matrix,
            user_message=text
        )

    elif any(
        lower == greeting
        or lower.startswith(
            greeting + " "
        )
        for greeting in greeting_words
    ):
        append_chat_message(
            "user",
            text
        )

        append_chat_message(
            "assistant",
            (
                "Hi! 👋 Tell me what you want to cook, "
                "ask what you should use soon, or check "
                "what is available in your kitchen. "
                "You can also tap one of the quick choices."
            )
        )

    else:
        append_chat_message(
            "user",
            text
        )

        append_chat_message(
            "assistant",
            (
                "I can help with recipe suggestions, foods to use soon, "
                "and what is currently in your kitchen. You can type a "
                "question or use the quick choices below."
            )
        )

