# ---------------------------------------------------------
# GitHub review storage
# ---------------------------------------------------------

REVIEW_CSV_HEADER = [
    "response_id",
    "timestamp_utc",
    "understandability",
    "trustworthiness",
    "usefulness",
    "visual_consistency",
    "comment"
]


def append_review_to_github(review):
    """
    Append one review to reviews/reviews.csv in the GitHub repo.

    Required Streamlit secrets:
      GITHUB_REVIEW_TOKEN
      GITHUB_REVIEW_REPO
    Optional:
      GITHUB_REVIEW_BRANCH (default: main)
      GITHUB_REVIEW_FILE   (default: reviews/reviews.csv)
    """
    token = st.secrets.get(
        "GITHUB_REVIEW_TOKEN"
    )

    repo = st.secrets.get(
        "GITHUB_REVIEW_REPO"
    )

    branch = st.secrets.get(
        "GITHUB_REVIEW_BRANCH",
        "main"
    )

    file_path = st.secrets.get(
        "GITHUB_REVIEW_FILE",
        "reviews/reviews.csv"
    )

    if not token or not repo:
        raise RuntimeError(
            "GitHub review storage is not configured. "
            "Add GITHUB_REVIEW_TOKEN and "
            "GITHUB_REVIEW_REPO to Streamlit Secrets."
        )

    api_url = (
        f"https://api.github.com/repos/"
        f"{repo}/contents/{file_path}"
    )

    headers = {
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
        "X-GitHub-Api-Version": "2022-11-28"
    }

    # Retry in case two users submit at almost the same time.
    for attempt in range(3):
        get_response = requests.get(
            api_url,
            headers=headers,
            params={"ref": branch},
            timeout=20
        )

        if get_response.status_code == 200:
            file_data = get_response.json()

            current_sha = file_data["sha"]

            existing_content = base64.b64decode(
                file_data["content"]
            ).decode(
                "utf-8"
            )

        elif get_response.status_code == 404:
            current_sha = None

            output = io.StringIO(
                newline=""
            )

            writer = csv.writer(
                output
            )

            writer.writerow(
                REVIEW_CSV_HEADER
            )

            existing_content = (
                output.getvalue()
            )

        else:
            raise RuntimeError(
                "Could not read reviews.csv from GitHub. "
                f"GitHub returned "
                f"{get_response.status_code}."
            )

        output = io.StringIO(
            newline=""
        )

        # Keep the existing CSV exactly as it is,
        # then append one properly escaped CSV row.
        output.write(
            existing_content
        )

        if (
            existing_content
            and not existing_content.endswith(
                "\n"
            )
        ):
            output.write(
                "\n"
            )

        writer = csv.writer(
            output
        )

        writer.writerow([
            review["response_id"],
            review["timestamp_utc"],
            review["understandability"],
            review["trustworthiness"],
            review["usefulness"],
            review["visual_consistency"],
            review["comment"]
        ])

        updated_content = (
            output.getvalue()
        )

        payload = {
            "message": (
                "Add ZWaste user review "
                f"{review['response_id']}"
            ),
            "content": base64.b64encode(
                updated_content.encode(
                    "utf-8"
                )
            ).decode(
                "ascii"
            ),
            "branch": branch
        }

        if current_sha:
            payload["sha"] = (
                current_sha
            )

        put_response = requests.put(
            api_url,
            headers=headers,
            json=payload,
            timeout=20
        )

        if put_response.status_code in (
            200,
            201
        ):
            return True

        # SHA conflict: fetch newest file and retry.
        if (
            put_response.status_code == 409
            and attempt < 2
        ):
            continue

        try:
            details = (
                put_response.json()
                .get(
                    "message",
                    "Unknown GitHub error"
                )
            )
        except Exception:
            details = (
                put_response.text
            )

        raise RuntimeError(
            "Could not save the review to GitHub. "
            f"GitHub returned "
            f"{put_response.status_code}: "
            f"{details}"
        )

    raise RuntimeError(
        "Could not save the review because the "
        "CSV changed during submission. "
        "Please try again."
    )


