    image_source = st.radio(
        "Choose an image source",
        [
            "Upload a photo",
            "Use camera"
        ],
        horizontal=True
    )

    image_file = None

    if image_source == "Upload a photo":
        image_file = st.file_uploader(
            "Choose a food photo",
            type=[
                "jpg",
                "jpeg",
                "png"
            ]
        )

    else:
        image_file = st.camera_input(
            "Take a food photo"
        )

    if image_file is not None:
        image_bytes = image_file.getvalue()

        current_image_id = hashlib.sha256(
            image_bytes
        ).hexdigest()

        if (
            st.session_state.uploaded_image_id
            != current_image_id
        ):
            st.session_state.uploaded_image_id = (
                current_image_id
            )

            st.session_state.last_detections = None

        uploaded_image = Image.open(
            image_file
        ).convert(
            "RGB"
        )

        image_col, action_col = st.columns(
            [1.25, 0.75]
        )

        with image_col:
            st.image(
                uploaded_image,
                caption="Your photo",
                use_container_width=True
            )

        with action_col:
            st.markdown(
                "#### Food Analysis"
            )

            analyze_clicked = st.button(
                "🔍 Check Food",
                type="primary",
                use_container_width=True
            )

            st.caption(
                "Supported foods: "
                + ", ".join(supported_items)
            )

        if analyze_clicked:
            try:
                with st.spinner(
                    "Detecting and checking your food..."
                ):
                    detector = get_object_detector()

                    detections, _ = predict_multiple_foods(
                        uploaded_image,
                        detector,
                        model,
                        mappings,
                        device
                    )

                st.session_state.last_detections = detections

            except Exception as error:
                st.session_state.last_detections = None

                st.error(
                    "The multi-food analysis could not be "
                    f"completed. Details: {error}"
                )

        detections = st.session_state.last_detections

        if detections is None:
            st.info(
                "Click **Check Food** to analyse the image."
            )

        elif not detections:
            st.warning(
                "No supported food regions were detected. "
                "Try a clearer image or add the food "
                "manually in My Kitchen."
            )

        else:
            scene_records = [
                detection_to_inventory_record(
                    detection,
                    current_image_id
                )
                for detection in detections
            ]

            detected_count = len(
                scene_records
            )

            st.success(
                f"Detected {detected_count} food item"
                f"{'s' if detected_count != 1 else ''}. "
                "Each detected item is kept separately "
                "in My Kitchen."
            )

            st.markdown(
                "### Detected foods"
            )

            st.caption(
                "Review each detected item below. Add one item at "
                "a time, or add all detected items together."
            )

            # Compact table-style header
            header_columns = st.columns(
                [0.75, 1.25, 1.25, 1.0, 1.0, 1.35, 0.9]
            )

            header_labels = [
                "",
                "Food",
                "Condition",
                "Food confidence",
                "Condition confidence",
                "What to do",
                "Add"
            ]

            for column, label in zip(
                header_columns,
                header_labels
            ):
                if label:
                    column.markdown(
                        f"**{label}**"
                    )

            st.divider()

            for detection_index, detection in enumerate(
                detections
            ):
                condition = friendly_condition(
                    detection["stage"]
                )

                action = friendly_action(
                    detection["stage"]
                )

                icon = status_icon(
                    detection["stage"]
                )

                food_confidence = clamp_probability(
                    detection[
                        "item_probability"
                    ]
                )

                stage_confidence = clamp_probability(
                    detection[
                        "stage_probability"
                    ]
                )

                row_columns = st.columns(
                    [0.75, 1.25, 1.25, 1.0, 1.0, 1.35, 0.9],
                    vertical_alignment="center"
                )

                with row_columns[0]:
                    st.image(
                        detection["crop"],
                        width=90
                    )

                with row_columns[1]:
                    st.markdown(
                        f"**{detection['item']}**"
                    )

                with row_columns[2]:
                    st.write(
                        f"{icon} {condition}"
                    )

                with row_columns[3]:
                    st.write(
                        percent_text(
                            food_confidence
                        )
                    )

                with row_columns[4]:
                    st.write(
                        percent_text(
                            stage_confidence
                        )
                    )

                with row_columns[5]:
                    st.write(
                        action
                    )

                with row_columns[6]:
                    if st.button(
                        "Add",
                        key=(
                            "add_detected_food_"
                            f"{detection_index}"
                        ),
                        use_container_width=True
                    ):
                        single_record = (
                            detection_to_inventory_record(
                                detection,
                                current_image_id
                            )
                        )

                        result_action = (
                            add_or_update_inventory_record(
                                single_record
                            )
                        )

                        reset_recipe_flow()

                        verb = (
                            "Added"
                            if result_action == "added"
                            else "Updated"
                        )

                        st.session_state.flash_message = (
                            f"{verb} {single_record['item']} "
                            "in My Kitchen."
                        )

                        st.rerun()

                with st.expander(
                    "🔎 Why this result?",
                    expanded=False
                ):
                    stage_name = str(
                        detection["stage"]
                    ).strip().lower()

                    if stage_name == "medium":
                        urgency = "High — Use Soon"
                        recommendation = (
                            "Prioritise this food when generating "
                            "recipes."
                        )

                    elif stage_name == "rotten":
                        urgency = "Do Not Use"
                        recommendation = (
                            "Exclude this food from recipe "
                            "generation."
                        )

                    else:
                        urgency = "Normal"
                        recommendation = (
                            "This food can be used normally."
                        )

                    explanation_columns = st.columns(
                        [0.32, 0.68]
                    )

                    overlay = detection.get(
                        "gradcam_overlay"
                    )

                    with explanation_columns[0]:
                        if overlay is not None:
                            st.image(
                                overlay,
                                caption=(
                                    "Grad-CAM model attention"
                                ),
                                width=180
                            )

                    with explanation_columns[1]:
                        st.markdown(
                            f"**Food:** {detection['item']}"
                        )

                        st.markdown(
                            f"**Condition:** {condition}"
                        )

                        st.markdown(
                            f"**Urgency:** {urgency}"
                        )

                        st.markdown(
                            "**Model attention:** "
                            "The highlighted areas contributed "
                            f"most strongly to the model's "
                            f"**{condition}** prediction."
                        )

                        st.markdown(
                            "**Recommended action:** "
                            f"{recommendation}"
                        )

                        st.info(
                            "The highlighted areas show model "
                            "attention only. They should not "
                            "automatically be interpreted as "
                            "physical damage or spoilage."
                        )

                        st.caption(
                            "Confidence values represent model "
                            "certainty, not a biological freshness "
                            "percentage."
                        )

                st.divider()

            if st.button(
                "➕ Add All Detected Foods to My Kitchen",
                type="primary",
                use_container_width=True
            ):
                added_count = 0
                updated_count = 0

                for record in scene_records:
                    result_action = (
                        add_or_update_inventory_record(
                            record
                        )
                    )

                    if result_action == "added":
                        added_count += 1
                    else:
                        updated_count += 1

                reset_recipe_flow()

                if updated_count:
                    st.session_state.flash_message = (
                        f"Added {added_count} and updated "
                        f"{updated_count} detected food"
                        f"{'s' if added_count + updated_count != 1 else ''} "
                        "in My Kitchen."
                    )
                else:
                    st.session_state.flash_message = (
                        f"Added {added_count} detected food item"
                        f"{'s' if added_count != 1 else ''} "
                        "to My Kitchen."
                    )

                st.rerun()

            st.caption(
                "Foods predicted as Rotten can remain in My "
                "Kitchen for tracking, but they are excluded "
                "from recipe recommendations."
            )


