# =========================================================
# PAGE 3 — RECIPE ASSISTANT
# =========================================================

if page == "🍳 Recipe Assistant":
    render_top_brand(page)
    show_flash_message()
    st.subheader(
        "🍳 Recipe Assistant"
    )

    st.caption(
        "Choose a quick option or type a message."
    )

    recipe_inventory = (
        build_recipe_inventory(
            st.session_state.inventory
        )
    )

    # -----------------------------------------------------
    # Render chat history from oldest to newest
    # -----------------------------------------------------

    candidate_clicked = None

    for event_index, event in enumerate(
        st.session_state.chat_events
    ):
        event_type = event.get(
            "type"
        )

        if event_type == "message":
            chat_bubble(
                event.get(
                    "role",
                    "assistant"
                ),
                event.get(
                    "content",
                    ""
                )
            )

        elif event_type == "candidates":
            st.markdown(
                '<div class="zw-assistant-content">',
                unsafe_allow_html=True
            )

            for number, record in enumerate(
                event.get(
                    "candidates",
                    []
                ),
                start=1
            ):
                chosen = render_candidate_card(
                    record,
                    number,
                    event_index,
                    event.get(
                        "active",
                        False
                    )
                )

                if chosen:
                    candidate_clicked = (
                        event_index,
                        number - 1,
                        record
                    )

            st.markdown(
                "</div>",
                unsafe_allow_html=True
            )

        elif event_type == "recipe":
            st.markdown(
                '<div class="zw-assistant-content">',
                unsafe_allow_html=True
            )

            render_recipe_result(
                event
            )

            st.markdown(
                "</div>",
                unsafe_allow_html=True
            )

    # -----------------------------------------------------
    # Handle candidate selection
    # -----------------------------------------------------

    if candidate_clicked is not None:
        (
            event_index,
            candidate_index,
            selected_record
        ) = candidate_clicked

        # Disable the old candidate buttons after selection.
        st.session_state.chat_events[
            event_index
        ][
            "active"
        ] = False

        selected_name = selected_record[
            "name"
        ]

        append_chat_message(
            "user",
            f"I want to cook {selected_name}"
        )

        append_chat_message(
            "assistant",
            (
                f"Great choice! I'll adapt {selected_name} "
                "using only the ingredients allowed from "
                "your kitchen."
            )
        )

        api_key = get_api_key()

        if not api_key:
            append_chat_message(
                "assistant",
                (
                    "The recipe-generation service is not "
                    "connected yet. Add OPENAI_API_KEY to "
                    "Streamlit Secrets, then choose the "
                    "recipe again."
                )
            )

        else:
            selected_candidate = pd.DataFrame(
                [
                    selected_record
                ]
            )

            try:
                with st.spinner(
                    "Preparing your recipe..."
                ):
                    (
                        adapted,
                        report,
                        attempts
                    ) = generate_validated_recipe(
                        recipe_inventory,
                        selected_candidate,
                        api_key,
                        model_name=LLM_MODEL,
                        max_attempts=1
                    )

                st.session_state.recipe_result = {
                    "candidate": selected_record,
                    "adapted": adapted,
                    "report": report,
                    "attempts": attempts
                }

                if (
                    adapted is not None
                    and report is not None
                    and report.get(
                        "usable_recipe",
                        False
                    )
                ):
                    append_chat_message(
                        "assistant",
                        (
                            "Done! I adapted the recipe to "
                            "your kitchen and checked it before "
                            "showing it to you."
                        )
                    )
                else:
                    append_chat_message(
                        "assistant",
                        (
                            "I couldn't make an approved "
                            "version of that recipe using only "
                            "your current ingredients. You can "
                            "choose another option below."
                        )
                    )

                st.session_state.chat_events.append(
                    {
                        "type": "recipe",
                        "role": "assistant",
                        "adapted": adapted,
                        "report": report,
                        "attempts": attempts
                    }
                )

                st.session_state.scroll_to_latest = True

            except Exception as error:
                append_chat_message(
                    "assistant",
                    (
                        "I couldn't prepare that recipe "
                        f"right now. Please try again. ({error})"
                    )
                )

        st.rerun()

    # -----------------------------------------------------
    # Quick choices are always available
    # -----------------------------------------------------

    st.markdown(
        '<div class="zw-choice-title">'
        'Quick choices — tap any option'
        '</div>',
        unsafe_allow_html=True
    )

    choice1, choice2 = st.columns(
        2
    )

    with choice1:
        suggest_clicked = st.button(
            "🍳 Suggest some recipes",
            key="chat_suggest",
            use_container_width=True
        )

        kitchen_clicked = st.button(
            "🥕 What's in my kitchen?",
            key="chat_kitchen",
            use_container_width=True
        )

    with choice2:
        soon_clicked = st.button(
            "🟠 What should I use soon?",
            key="chat_soon",
            use_container_width=True
        )

        help_clicked = st.button(
            "💡 What can you do?",
            key="chat_help",
            use_container_width=True
        )

    chosen_action = None

    if suggest_clicked:
        chosen_action = (
            "🍳 Suggest some recipes"
        )

    elif soon_clicked:
        chosen_action = (
            "🟠 What should I use soon?"
        )

    elif kitchen_clicked:
        chosen_action = (
            "🥕 What's in my kitchen?"
        )

    elif help_clicked:
        chosen_action = (
            "💡 What can you do?"
        )

    if chosen_action is not None:
        with st.spinner(
            "Thinking..."
        ):
            process_recipe_action(
                chosen_action,
                recipe_inventory,
                recipes,
                vectorizer,
                recipe_matrix
            )

        st.rerun()

    # -----------------------------------------------------
    # Users can also type naturally
    # -----------------------------------------------------

    typed_message = st.chat_input(
        "Type a message... e.g. What can I cook?"
    )

    if typed_message:
        with st.spinner(
            "Thinking..."
        ):
            process_typed_message(
                typed_message,
                recipe_inventory,
                recipes,
                vectorizer,
                recipe_matrix
            )

        st.rerun()

    clear_col, spacer_col = st.columns(
        [1, 3]
    )

    with clear_col:
        if st.button(
            "↻ New conversation",
            key="chat_reset",
            use_container_width=True
        ):
            st.session_state.chat_events = (
                initial_chat_events()
            )

            st.session_state.recipe_candidates = None
            st.session_state.recipe_result = None
            st.session_state.selected_recipe = None
            st.session_state.suggested_recipe_names = []
            st.session_state.scroll_to_latest = True

            st.rerun()

    # Keep the newest part of the conversation visible.
    if st.session_state.scroll_to_latest:
        scroll_chat_to_latest()
        st.session_state.scroll_to_latest = False
